import csv
from collections import defaultdict

ts_set='1213f3a8-c23d-55b5-8187-4712d49a82ae'
ts_temp='baef86cb-2941-5d61-87b0-ffa91d79f23a'

vals=defaultdict(list)
with open(VALUES_CSV) as f:
    r=csv.DictReader(f)
    for row in r:
        if row['timeseries_id'] in (ts_set, ts_temp):
            vals[row['timeseries_id']].append((row['timestamp'],float(row['value'])))
for k,v in vals.items():
    v.sort()

def occ_avg(series, start, end):
    sel=[]
    for (t,v) in series:
        d=t[:10]
        if start<=d<=end:
            hr=int(t[11:13])
            if 8<=hr<=17:
                sel.append(v)
    return sum(sel)/len(sel) if sel else None, len(sel)

for name in ('2018-05-01 2018-05-31','2018-06-01 2018-06-14','2018-06-15 2018-06-30','2018-07-01 2018-07-31'):
    s,e=name.split()
    ta,na=occ_avg(vals[ts_temp],s,e)
    sa,ns=occ_avg(vals[ts_set],s,e)
    print(name,'temp',round(ta,3) if ta else None,'set',sa,'n',na)
